import { useRef, useState } from 'react';

const lanes = ['Draft', 'Review', 'Approved'] as const;
type Lane = typeof lanes[number];
type Card = { id: string; title: string; lane: Lane; reason: string };
const allowed: Record<Lane, readonly Lane[]> = { Draft: ['Review'], Review: ['Draft', 'Approved'], Approved: [] };
const initial: Card[] = [
  { id: 'WR-18', title: 'Renewal brief', lane: 'Draft', reason: '' },
  { id: 'WR-24', title: 'Site return', lane: 'Review', reason: '' },
  { id: 'WR-31', title: 'Baseline plan', lane: 'Approved', reason: '' },
];

export default function GuardedWorkflowKanban() {
  const [cards, setCards] = useState(initial);
  const [destinations, setDestinations] = useState<Record<string, Lane | ''>>({});
  const [message, setMessage] = useState('');
  const [returning, setReturning] = useState('');
  const [note, setNote] = useState('');
  const locks = useRef(new Set<string>());
  const [pending, setPending] = useState<string[]>([]);
  const dialog = useRef<HTMLDialogElement>(null);

  async function apply(card: Card, lane: Lane, reason: string) {
    if (locks.current.has(card.id) || !allowed[card.lane].includes(lane)) return;
    locks.current.add(card.id);
    setPending([...locks.current]);
    try {
      await new Promise<void>(resolve => requestAnimationFrame(() => resolve()));
      setCards(rows => rows.map(row => row.id === card.id && row.lane === card.lane
        ? { ...row, lane, reason: reason || row.reason } : row));
      setMessage(card.id + ' moved to ' + lane + '.');
    } finally {
      locks.current.delete(card.id);
      setPending([...locks.current]);
    }
  }

  function request(id: string, lane: Lane) {
    const card = cards.find(row => row.id === id);
    if (!card || locks.current.has(id)) return;
    if (!allowed[card.lane].includes(lane)) {
      setMessage(id + ' stays in ' + card.lane + ': transition to ' + lane + ' is unavailable.');
    } else if (lane === 'Draft') {
      setReturning(id);
      setNote('');
      dialog.current?.showModal();
    } else void apply(card, lane, '');
  }

  return <section className="grid gap-3 text-start [&_button]:rounded-sm [&_button]:border [&_button]:border-[var(--border-strong)] [&_button]:px-2 [&_button]:py-1 [&_button:disabled]:opacity-50 [&_button[aria-pressed=true]]:bg-[var(--accent-tint)] [&_select]:rounded-sm [&_select]:border [&_input:not([type=checkbox])]:border [&_textarea]:border [&_dialog]:bg-[var(--bg-surface)] [&_dialog]:text-[var(--ink-primary)]">
    <div className="grid gap-2 sm:grid-cols-3">{lanes.map(lane =>
      <section key={lane} aria-label={lane} className="min-w-0 rounded-sm border p-2"
        onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); request(e.dataTransfer.getData('text/plain'), lane); }}>
        <h3 className="mb-2 font-semibold">{lane}</h3>
        {cards.filter(card => card.lane === lane).map(card =>
          <article className="mb-2 grid gap-2 border-s-2 ps-2" key={card.id} aria-label={card.id}
            draggable onDragStart={e => e.dataTransfer.setData('text/plain', card.id)}>
            <small className="font-mono">{card.id}</small><strong>{card.title}</strong>
            {card.reason && <p>Return note: {card.reason}</p>}
            <label className="grid gap-1 text-sm">Destination
              <select aria-label={'Destination for ' + card.id} value={destinations[card.id] ?? ''}
                onChange={e => setDestinations({ ...destinations, [card.id]: e.target.value as Lane | '' })}>
                <option value="">Choose lane</option>{lanes.map(target => <option key={target}>{target}</option>)}
              </select>
            </label>
            <button type="button" disabled={!destinations[card.id] || pending.includes(card.id)}
              onClick={() => { const target = destinations[card.id]; if (target) request(card.id,target); }}>Move</button>
          </article>)}
      </section>)}</div>
    <p role="status" aria-live="polite">{message}</p>
    <dialog ref={dialog} aria-label="Return to draft" className="max-w-full rounded-sm border p-4"
      onClick={e => { if (e.target === e.currentTarget) dialog.current?.close(); }} onClose={() => { setReturning(''); setNote(''); }}>
      <form className="grid gap-2" onSubmit={e => {
        e.preventDefault();
        const card = cards.find(row => row.id === returning);
        if (card && note.trim()) { void apply(card, 'Draft', note.trim()); dialog.current?.close(); }
      }}>
        <label>Return note<textarea autoFocus required maxLength={300} value={note} className="block w-full" onChange={e => setNote(e.target.value)} /></label>
        <button type="submit" disabled={!note.trim()}>Confirm return</button>
        <button type="button" onClick={() => dialog.current?.close()}>Cancel</button>
      </form>
    </dialog>
  </section>;
}
